def in_dirs(L,m,k=10,nd=8):
    A,B=diff[f'model.layers.{L}.{m}']
    ln = W[f'model.layers.{L}.input_layernorm.weight' if 'self_attn' in m else f'model.layers.{L}.post_attention_layernorm.weight'].float()
    s=(En*ln)@B.float()
    res=[]
    for j in range(nd):
        res.append(([tok.decode([i]) for i in torch.topk(s[:,j],k).indices.tolist()],[tok.decode([i]) for i in torch.topk(-s[:,j],k).indices.tolist()]))
    return res
